#include <iostream>
#include <string>
#include <vector>
#include <array>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string mdp;
    int a;
    cin >> mdp >> a;

    vector<string> tab(a);
    for (string& s : tab) cin >> s;

    if (mdp.size() != 2 || a == 0) {
        cout << "NO";
        return 0;
    }

    for (const string& s : tab) {
        if (s.find(mdp) != string::npos) {
            cout << "YES";
            return 0;
        }
    }

    if (a == 1) {
        if (tab[0].back() == mdp[0] && tab[0].front() == mdp[1])
            cout << "YES";
        else
            cout << "NO";
        return 0;
    }

    array<int, 256> firstCount{};
    for (const string& s : tab)
        ++firstCount[static_cast<unsigned char>(s.front())];

    for (const string& s : tab) {
        if (s.back() != mdp[0]) continue;

        unsigned char wanted = static_cast<unsigned char>(mdp[1]);
        int available = firstCount[wanted];

        if (s.front() == mdp[1]) --available;

        if (available > 0) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string mdp;
    int n;
    cin >> mdp >> n;

    vector<string> tab(n);
    for (string& s : tab) cin >> s;

    if (mdp.size() != 2) {
        cout << "NO";
        return 0;
    }

    long long suffixCount = 0, prefixCount = 0, intersectionCount = 0;

    for (const string& s : tab) {
        if (s.find(mdp) != string::npos) {
            cout << "YES";
            return 0;
        }

        bool suffixMatch = s.back() == mdp[0];
        bool prefixMatch = s.front() == mdp[1];

        suffixCount += suffixMatch;
        prefixCount += prefixMatch;
        intersectionCount += suffixMatch && prefixMatch;
    }

    bool possible;
    if (n == 1)
        possible = suffixCount && prefixCount;
    else
        possible = suffixCount * prefixCount > intersectionCount;

    cout << (possible ? "YES" : "NO");
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string mdp;
    int a;
    cin >> mdp >> a;

    vector<string> tab(a);
    for (string& s : tab) cin >> s;

    if (mdp.size() != 2) {
        cout << "NO";
        return 0;
    }

    int firstLeft = -1, firstRight = -1;
    int leftCount = 0, rightCount = 0;

    for (int i = 0; i < a; ++i) {
        if (tab[i].find(mdp) != string::npos) {
            cout << "YES";
            return 0;
        }

        if (!tab[i].empty() && tab[i].back() == mdp[0]) {
            if (firstLeft == -1) firstLeft = i;
            ++leftCount;
        }

        if (!tab[i].empty() && tab[i].front() == mdp[1]) {
            if (firstRight == -1) firstRight = i;
            ++rightCount;
        }
    }

    bool possible = false;

    if (leftCount > 0 && rightCount > 0) {
        if (a == 1) {
            possible = true;
        } else if (firstLeft != firstRight || leftCount > 1 || rightCount > 1) {
            possible = true;
        }
    }

    cout << (possible ? "YES" : "NO");
    return 0;
}

