    vector<string> words(n);
    for (string& word : words) cin >> word;

    if (mdp.size() != 2) {
        cout << "NO";
        return 0;
    }

    for (const string& word : words) {
        if (word.find(mdp) != string::npos) {
            cout << "YES";
            return 0;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (words[i].empty() || words[i].back() != mdp[0]) continue;

        for (int j = 0; j < n; ++j) {
            if ((i != j || n == 1) &&
                !words[j].empty() &&
                words[j].front() == mdp[1]) {
                cout << "YES";
                return 0;
            }
        }
    }

    cout << "NO";
    return 0;
}

