    string mdp;
    int a;

    cin >> mdp >> a;

    vector<string> tab(a);
    for (string& s : tab) {
        cin >> s;
    }

    if (mdp.size() != 2 || a == 0) {
        cout << "NO";
        return 0;
    }

    if (a == 1) {
        cout << ((tab[0] + tab[0]).find(mdp) != string::npos ? "YES" : "NO");
        return 0;
    }

    for (const string& s : tab) {
        if (s.find(mdp) != string::npos) {
            cout << "YES";
            return 0;
        }
    }

    int starts[256] = {};
    for (const string& s : tab) {
        if (!s.empty()) {
            ++starts[static_cast<unsigned char>(s.front())];
        }
    }

    for (const string& s : tab) {
        if (s.empty() || s.back() != mdp[0]) {
            continue;
        }

        int candidates = starts[static_cast<unsigned char>(mdp[1])];
        if (s.front() == mdp[1]) {
            --candidates;
        }

        if (candidates > 0) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

